from dilithium_py.dilithium.default_parameters import ZKDilithiumBB
from dilithium_py.dilithium.default_parameters import ZKDilithiumKB
from .poseidon_sponge.poseidon_sponge_wrapper import PoseidonKoalaBearSponge

# An example of ZK-ETHDilithium with Baby Bear and Koala Bear together with and Keccak256PRNG.
msg = b"We are ZKNox."

for D in [ZKDilithiumKB]:#[ZKDilithiumBB, ZKDilithiumKB]:
    # # Random keygen
    # pk, sk = D.keygen(_xof = PoseidonKoalaBearSponge, _xof2=PoseidonKoalaBearSponge, zk=True)
    
    # Hardcoded keygen
    sk = bytes.fromhex("")
    pk = bytes.fromhex("")
    
    sig = D.sign(sk, msg, deterministic=True, _xof = PoseidonKoalaBearSponge, _xof2=PoseidonKoalaBearSponge, zk=True)
    assert D.verify(pk, msg, sig, _xof = PoseidonKoalaBearSponge, _xof2=PoseidonKoalaBearSponge, zk=True)

    print("sig: {}".format(sig.hex()))
    print("msg: {}".format(msg.hex()))
    print("pk: {}".format(pk.hex()))
    print("sk: {}".format(sk.hex()))
    
    # # PK
    ahat, tr, t1new = D.pk_for_eth(pk, _xof=PoseidonKoalaBearSponge, _xof2=PoseidonKoalaBearSponge, zk=True)
    c_tilde, z, h = D._unpack_sig(sig)
    rho, t1 = D._unpack_pk(pk)
    print("c_tilde = {}".format(c_tilde.hex()))
    print("z = {}".format(z))
    print("zcoeffs: ", z[0,0].coeffs[:10])
    print("h = {}".format(h))
    print("rho = {}".format(rho.hex()))
    print("t1 = {}".format(t1))
    print("tr = {}".format(tr.hex()))
    print("aHat = {}".format(ahat))

    # Sample in ball
    c = D.R.sample_in_ball(c_tilde, D.tau, _xof=PoseidonKoalaBearSponge)
    coeffs = list(c.coeffs)
    print("cSampleInBall = {}".format(coeffs))

    msg_mldsa = bytes([0]) + bytes([len(b"")]) + b"" + msg
    mu = D._h(tr + msg_mldsa, 64, _xof=PoseidonKoalaBearSponge)
    print("mu = {}".format(mu.hex()))

    # # Compact PK for Solidity
    # A_hat_compact = A_hat.compact_256(32)
    # t1_new_compact = t1_new.compact_256(32)

